/**
 * Top-sites study — the research dataset behind the dashboard.
 *
 * Derived, committed artifact: `data/top-sites-study.json`, generated by
 * `scripts/build-top-sites-data.mjs` from the crawl tools in `tools/crawl/`
 * (pinned Tranco list `64VVX`, JS-wall measurement + robots.txt policy).
 * Never hand-edit the JSON — re-run the script after a crawl.
 *
 * The study: two passes per homepage with the same user agent — plain HTTP vs.
 * headless Chromium — so JavaScript execution is the only variable. Coverage =
 * share of the browser-visible content that a non-rendering client receives.
 * Full method, caveats, and license live on the dashboard's methodology cards.
 */
import raw from "./data/top-sites-study-1k.json";
import crawlerGroupsJson from "./crawler-groups.json";

/* --------------------------------- Types ---------------------------------- */

export type RobotsVerdict = "block" | "allow" | "partial" | "unset";

export type SiteClassification =
  | "measured"
  | "raw_blocked"
  | "both_blocked"
  | "robots_excluded"
  | "render_incomplete"
  | "render_failed"
  | "crawl_error";

export interface StudySiteMetrics {
  rawWords: number;
  renderedWords: number;
  coverage: number;
  /** JSON-LD @types present in raw HTML / in the rendered DOM / only in the rendered DOM. */
  jsonLdRaw: string[];
  jsonLdRendered: string[];
  jsonLdMissingFromRaw: string[];
  headingsCoverage: number | null;
  titleDiffers: boolean;
  /** Rendered text looked like an anti-bot interstitial. */
  challengeLike: boolean;
  /** CJK-dominant page (character-bigram tokenisation). */
  cjk: boolean;
}

export interface StudySite {
  rank: number;
  domain: string;
  /** Curated vertical cut from the crawl analysis (only the hand-curated ~84 carry one). */
  group?: string | null;
  classification: SiteClassification;
  /** % of rendered content present in raw HTML — only meaningful when measured. */
  coverage: number | null;
  robots: {
    /** HTTP status of the robots.txt fetch. 0 = no response. */
    status: number;
    wildcard: RobotsVerdict;
    /** Per-crawler verdicts decoded against `meta.crawlers` order. */
    verdicts: Record<string, RobotsVerdict>;
  };
  metrics: StudySiteMetrics | null;
  note?: string;
}

export interface StudyGroup {
  name: string;
  n: number;
  measured: number;
  medianCoverage: number | null;
  blocked: number;
  robotsExcluded: number;
}

export interface TopSitesStudy {
  meta: {
    study: string;
    method: string;
    /** Local date of the two back-to-back crawl runs. */
    runDate: string;
    generatedAt: string;
    runs: number;
    license: string;
    tranco: {
      source: string;
      listId: string;
      createdOn: string;
      window: { start: string; end: string };
      combinationMethod: string;
      providers: string[];
      note: string;
    };
    crawlers: string[];
    /** Crawl-extent fields written by the extended-study build. */
    counts?: { crawled: number; measured: number } & Record<string, number>;
    highestRankCrawled?: number;
    /** Crawl passes per Tranco rank range, e.g. { "1-500": 2, "501-2132": 1 }. */
    runsByRankRange?: Record<string, number>;
  };
  summary: {
    counts: Record<SiteClassification, number>;
    coverage: {
      measured: number;
      median: number;
      p25: number;
      p75: number;
      min: number;
      max: number;
    };
    histogram: { binSize: number; bins: number[] };
    robots: { sitesWithRobots: number; tokens: Record<string, Record<RobotsVerdict, number>> };
    rankCoverage: { n: number; r: number; note: string };
    gptBot: { blocked: StudyCorrelation; open: StudyCorrelation };
  };
  stability: {
    sitesCompared: number;
    classificationChanged: number;
    bothMeasured: number;
    medianAbsDelta: number;
    p90AbsDelta: number;
    movedOver5pp: number;
  };
  groups: StudyGroup[];
  sites: StudySite[];
}

export interface StudyCorrelation {
  n: number;
  measured: number;
  measuredShare: number;
  medianCoverage: number | null;
  unreadable: number;
  unreadableShare: number;
}

/* --------------------------------- Decode ---------------------------------- */

const CODE_TO_VERDICT: Record<string, RobotsVerdict> = {
  b: "block",
  a: "allow",
  p: "partial",
  u: "unset",
};

type RawStudy = {
  meta: TopSitesStudy["meta"];
  summary: TopSitesStudy["summary"];
  stability: TopSitesStudy["stability"];
  groups: StudyGroup[];
  sites: {
    rank: number;
    domain: string;
    group?: string | null;
    classification: SiteClassification;
    coverage: number | null;
    robots: { status: number; wildcard: RobotsVerdict; codes: string | null };
    metrics?: StudySiteMetrics;
    note?: string;
  }[];
};

function decodeSite(site: RawStudy["sites"][number], crawlers: string[]): StudySite {
  const verdicts: Record<string, RobotsVerdict> = {};
  crawlers.forEach((token, index) => {
    verdicts[token] = CODE_TO_VERDICT[site.robots.codes?.[index] ?? "u"] ?? "unset";
  });
  return {
    rank: site.rank,
    domain: site.domain,
    group: site.group ?? null,
    classification: site.classification,
    coverage: site.coverage,
    robots: { status: site.robots.status, wildcard: site.robots.wildcard, verdicts },
    metrics: site.metrics ?? null,
    note: site.note,
  };
}

/** Decode a crawl-study JSON (any rank range) into display-ready sites. */
export function decodeStudy(rawStudy: RawStudy): TopSitesStudy {
  return {
    meta: rawStudy.meta,
    summary: rawStudy.summary,
    stability: rawStudy.stability,
    groups: rawStudy.groups,
    sites: rawStudy.sites.map((site) => decodeSite(site, rawStudy.meta.crawlers)),
  };
}

/**
 * The study: every crawled site (Tranco ranks 1 to `meta.highestRankCrawled`, infrastructure
 * domains filtered), kept whether readable or not. Ranks 1–500 got two runs, later ranks one,
 * and crawling continued until the readable target was met — see `meta.runsByRankRange`.
 */
export const topSitesStudy: TopSitesStudy = decodeStudy(raw as unknown as RawStudy);

