/* --------------------------- Rankings & method ----------------------------- */

/**
 * Why these sites are the top sites: five independent providers publish
 * their own top-1M rankings, and Tranco combines them into one list.
 * Descriptions follow Tranco's published methodology (tranco-list.eu).
 */
export const rankingSources: { name: string; measures: string }[] = [
  { name: "Chrome UX Report", measures: "real-user page visits measured by Chrome" },
  { name: "Farsight DNSDB", measures: "passive DNS lookups seen across global resolvers" },
  { name: "Majestic", measures: "link-graph popularity from a web-scale crawl" },
  { name: "Cloudflare Radar", measures: "DNS and network traffic seen by Cloudflare" },
  { name: "Cisco Umbrella", measures: "DNS queries from a large resolver network" },
];

/** Depth of the Tranco list that was crawled, and how many of those entries were infrastructure. */
const listDepth = topSitesStudy.meta.highestRankCrawled ?? Math.max(...topSitesStudy.sites.map((site) => site.rank));
const infraRemoved = listDepth - topSitesStudy.sites.length;

export const rankMethodology = {
  aggregation:
    "Tranco combines the five providers' rankings with the Dowdall method — a position-weighted rank aggregation — and averages daily over a 30-day window, so no single provider's noise decides a rank.",
  listVersion:
    "This study pins list 64VVX: created 16 Oct 2026, its 30-day window ran 17 Sep – 16 Oct 2026. Pinning the list keeps every number on this page reproducible.",
  pool: "Candidates come from Tranco's manipulation-hardened top 1M (PLD-filtered, sources updated daily).",
  curation: `Infrastructure domains — CDNs, DNS/hosting backends, ad and telemetry networks, auth portals, shorteners — were removed before the crawl: ${infraRemoved} of the first ${listDepth.toLocaleString("en-US")} Tranco entries (${Math.round((100 * infraRemoved) / listDepth)}%). The ${topSitesStudy.sites.length.toLocaleString("en-US")} content sites crawled therefore span original ranks 1–${listDepth.toLocaleString("en-US")}.`,
  meaning:
    "A rank measures reach — how much of the world's browsing and looking-up a domain accounts for. It says nothing about SEO health, content quality, or whether AI crawlers can read the pages. That is exactly why the study pairs the list with machine-readability measurements.",
};

const { stability } = topSitesStudy;
const cjkPages = topSitesStudy.sites.filter((site) => site.metrics?.cjk).length;

/** Method, stability evidence, and caveats — mirrors docs/data-assets-and-interactives.md §6.3. */
export const studyMethod = {
  passes: [
    "Pass 1 — plain HTTP: fetch each homepage as a non-rendering client would. This is what most AI crawlers receive.",
    "Pass 2 — headless Chromium: load the same URL with JavaScript, images, fonts, and media blocked. Same user agent in both passes, so JS execution is the only variable.",
    "Coverage = share of the browser-visible page tokens that are present in the raw HTML. Same idea for JSON-LD types and headings.",
  ],
  coverage:
    "Robots.txt was honoured for every site (RFC 9309 group semantics, wildcards and specific groups both parsed), ≤4 sites in flight, sequential per domain, one identifying user agent.",
  stability: [
    `Ranks 1–${stability.sitesCompared.toLocaleString("en-US")} were crawled in two back-to-back runs, thousands of page loads — classification changed for ${stability.classificationChanged} of ${stability.sitesCompared.toLocaleString("en-US")} sites (${Math.round((100 * stability.classificationChanged) / stability.sitesCompared)}%).`,
    `Among the ${stability.bothMeasured.toLocaleString("en-US")} sites readable in both runs, the median coverage delta was ${stability.medianAbsDelta} percentage points (p90: ${stability.p90AbsDelta}pp). Headline aggregates are stable; wall-adjacent verdicts flicker.`,
  ],
  caveats: [
    `Ranks 1–${stability.sitesCompared.toLocaleString("en-US")} got two runs; every later rank got one, so stability figures cover the first ${stability.sitesCompared.toLocaleString("en-US")} sites only. Crawling continued until ${topSitesStudy.summary.counts.measured.toLocaleString("en-US")} sites were readable.`,
    "Homepage only, desktop viewport; inner pages are audited for a subset only.",
    "Coverage is token-set overlap — an upper bound, not order- or context-aware.",
    "Anti-bot systems serve different pages to different clients; a handful of verdicts sit next to a wall and can move between runs.",
    `${cjkPages} CJK-dominant pages are tokenised as character bigrams, so their word counts are not directly comparable.`,
    "The dataset is neutral to the sites it measures: inclusion is not an endorsement, exclusion (robots) is not criticism.",
  ],
  license: {
    name: "CC BY 4.0",
    detail:
      "Derived metrics (coverage %, classifications, robots.txt verdicts) are published under CC BY 4.0 with the pinned list ID and exclusion list. Raw third-party HTML is not republished.",
  },
};

/* ---------------------------- Crawler groups ------------------------------- */

export interface CrawlerGroup {
  id: string;
  label: string;
  blurb: string;
  tokens: string[];
}

/** Taxonomy for the policy view. Groups are ours; verdicts come from the crawl. */
export const crawlerGroups: CrawlerGroup[] = crawlerGroupsJson;

/* ------------------------------- Derived view ------------------------------ */

/** Histogram axis labels — first, middle, and last bins. */
export const coverageHistogramLabels = ["0–9%", "50–59%", "90–100%"];

/** Display-safe robots.txt status labels. */
export function robotsStatusLabel(status: number): string {
  if (status === 0) return "No response";
  if (status === 200) return "Served";
  if (status === 403) return "Challenge (403)";
  if (status === 404) return "Not found (404)";
  return `HTTP ${status}`;
}
